@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ## Energy per gram from nutrition labels

    The calories printed on a food label are not measured for each product.
    They are calculated from the label's own composition with **Atwater
    factors**: an energy per gram for each macronutrient,

    $$
    E = a\,m_\text{fat} + b\,m_\text{carbohydrate} + c\,m_\text{protein},
    $$

    where $E$ is the energy of one serving (kcal) and $m$ are the masses (g)
    in that serving. Each label gives one equation in the three unknowns
    $a$, $b$, and $c$, so three labels give a $3\times3$ linear system
    $\mathbf{A}\mathbf{x}=\mathbf{E}$, with one row of masses per food.

    This notebook reads the labels from photos with optical character
    recognition (OCR) running in your browser, so the photos never leave your
    computer. Upload photos of Canadian *Nutrition Facts* tables, or use the
    four sample labels below.
    """)
    return


@app.cell(hide_code=True)
def _(mo):
    photos = mo.ui.file(
        filetypes=[".png", ".jpg", ".jpeg", ".webp"],
        multiple=True,
        kind="area",
        label="Drop or choose photos of Nutrition Facts tables (one table per photo)",
    )
    photos
    return (photos,)


@app.cell(hide_code=True)
def _(Image, ImageOps, SAMPLE_LABELS, base64, io, photos):
    if photos.value:
        labels = [(f.name.rsplit(".", 1)[0], ImageOps.exif_transpose(Image.open(io.BytesIO(f.contents))))
                  for f in photos.value]
    else:
        labels = [(name, Image.open(io.BytesIO(base64.b64decode(data))))
                  for name, data in SAMPLE_LABELS.items()]
    labels = [(name, img.convert("L")) for name, img in labels]
    return (labels,)


