@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Step 2: even out the lighting

    A phone photo is brighter on one side of the label than the other, and a
    curved package adds shading. A grayscale *closing* (a running maximum
    followed by a running minimum over a square window wider than the text
    strokes) removes the dark letters and leaves an estimate of the local
    paper brightness. Dividing the photo by that background makes the paper
    uniformly white while keeping the letters dark. Each table is then
    enlarged so its long side is 1800 pixels, and three copies, rotated by
    −2°, 0°, and +2°, are sent to OCR. A slightly tilted photo reads best
    when one of the copies straightens its lines.
    """)
    return


@app.cell(hide_code=True)
def _(Image, ImageFilter, base64, crop, io, labels, ndimage, np):
    ROTATIONS = (-2.0, 0.0, 2.0)

    def even_lighting(gray, target=1800):
        """Rescale a grayscale table and divide out its slowly varying background."""
        _s = target / max(gray.size)
        _g = gray.resize((round(gray.width * _s), round(gray.height * _s)), Image.Resampling.LANCZOS)
        _a = np.asarray(_g, float)
        _k = max(15, int(min(_a.shape) / 25))
        _half = ndimage.grey_closing(_a[::2, ::2], size=(_k // 2, _k // 2))
        _background = ndimage.zoom(ndimage.uniform_filter(_half, _k // 2), 2, order=1)[:_a.shape[0], :_a.shape[1]]
        _flat = np.clip(255 * _a / np.maximum(_background, 1), 0, 255).astype(np.uint8)
        return Image.fromarray(_flat).filter(ImageFilter.UnsharpMask(2, 80, 2))

    def data_url(img):
        _buf = io.BytesIO()
        img.save(_buf, "JPEG", quality=92)
        return "data:image/jpeg;base64," + base64.b64encode(_buf.getvalue()).decode()

    prepared = []
    for (_name, _img), _c in zip(labels, crop.value):
        _W, _H = _img.size
        _box = (int(_c["x"][0] / 100 * _W), int(_c["y"][0] / 100 * _H),
                int(_c["x"][1] / 100 * _W), int(_c["y"][1] / 100 * _H))
        prepared.append((_name, even_lighting(_img.crop(_box))))
    ocr_images = [data_url(_img) for _, _img in prepared]
    return ROTATIONS, ocr_images, prepared


@app.cell(hide_code=True)
def _(plt, prepared):
    _n = len(prepared)
    _fig, _axes = plt.subplots(1, _n, figsize=(3.2 * _n, 3.6), squeeze=False)
    for _ax, (_name, _img) in zip(_axes[0], prepared):
        _ax.imshow(_img, cmap="gray", vmin=0, vmax=255)
        _ax.set_title(f"{_name}: even lighting")
        _ax.axis("off")
    _fig.tight_layout()
    _fig
    return


@app.cell(hide_code=True)
def _(anywidget, traitlets):
    class TesseractOCR(anywidget.AnyWidget):
        """Run Tesseract.js (WebAssembly) on a list of image data URLs in the browser."""

        _esm = r"""
        const TESSERACT = "https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.esm.min.js";
        const LANG_PATH = "https://cdn.jsdelivr.net/npm/@tesseract.js-data/eng@1.0.0/4.0.0_best_int";
        let workers = null;

        async function getWorkers(modes) {
          if (!workers) {
            workers = (async () => {
              const mod = await import(TESSERACT);
              const { createWorker } = mod.default ?? mod;
              return Promise.all(modes.map(async (psm) => {
                const w = await createWorker("eng", 1, { langPath: LANG_PATH });
                await w.setParameters({ tessedit_pageseg_mode: String(psm), preserve_interword_spaces: "1" });
                return w;
              }));
            })();
          }
          return workers;
        }

        function rotated(img, degrees) {
          const t = degrees * Math.PI / 180, c = Math.abs(Math.cos(t)), s = Math.abs(Math.sin(t));
          const canvas = document.createElement("canvas");
          canvas.width = Math.round(img.width * c + img.height * s);
          canvas.height = Math.round(img.width * s + img.height * c);
          const ctx = canvas.getContext("2d");
          ctx.fillStyle = "white";
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.translate(canvas.width / 2, canvas.height / 2);
          ctx.rotate(-t);  // positive angles turn counterclockwise, as in PIL
          ctx.drawImage(img, -img.width / 2, -img.height / 2);
          return canvas;
        }

        function loadImage(url) {
          return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = reject;
            img.src = url;
          });
        }

        function render({ model, el }) {
          const status = document.createElement("div");
          status.style.cssText = "font-family: sans-serif; font-size: 0.9rem; padding: 0.4rem 0;";
          el.appendChild(status);
          const show = (text) => { status.textContent = text; };

          async function run() {
            const key = model.get("request_key");
            const images = model.get("images");
            const modes = model.get("modes");
            const angles = model.get("angles");
            if (!images.length) { show("No images to read."); return; }
            if (model.get("result_key") === key) { show(`Finished ${images.length * angles.length * modes.length} readings.`); return; }
            try {
              show("Loading the OCR engine (about 4 MB, first run only)…");
              const ws = await getWorkers(modes);
              const jobs = [];
              for (const url of images) {
                const img = await loadImage(url);
                for (const a of angles) jobs.push(rotated(img, a));
              }
              const texts = new Array(jobs.length * modes.length);
              let done = 0;
              await Promise.all(ws.map(async (w, m) => {
                for (let j = 0; j < jobs.length; j++) {
                  const { data } = await w.recognize(jobs[j]);
                  texts[j * modes.length + m] = data.text;
                  done += 1;
                  show(`Reading… ${done} of ${texts.length} readings finished`);
                }
              }));
              if (model.get("request_key") !== key) return;
              model.set("texts", texts);
              model.set("result_key", key);
              model.set("error", "");
              model.save_changes();
              show(`Finished ${texts.length} readings.`);
            } catch (err) {
              model.set("error", String(err));
              model.save_changes();
              show("OCR failed: " + err);
            }
          }
          model.on("change:request_key", run);
          run();
        }
        export default { render };
        """
        images = traitlets.List([]).tag(sync=True)
        modes = traitlets.List([6, 11]).tag(sync=True)
        angles = traitlets.List([0.0]).tag(sync=True)
        request_key = traitlets.Unicode("").tag(sync=True)
        result_key = traitlets.Unicode("").tag(sync=True)
        texts = traitlets.List([]).tag(sync=True)
        error = traitlets.Unicode("").tag(sync=True)

    return (TesseractOCR,)


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Step 3: read the text with Tesseract

    [Tesseract](https://github.com/tesseract-ocr/tesseract) is an open-source
    OCR engine. It finds lines of text, then a small neural network reads
    each line as a sequence of characters. Here it runs in the browser as
    [Tesseract.js](https://tesseract.projectnaptha.com/), a WebAssembly build.
    Each table is read in two *page-segmentation modes*: mode 6 treats the
    table as one block of text lines, and mode 11 looks for scattered words.
    With three rotations, that makes six readings per table.
    """)
    return


@app.cell(hide_code=True)
def _(ROTATIONS, TesseractOCR, mo, ocr_images):
    import hashlib as _hashlib

    _key = _hashlib.sha1("".join(ocr_images).encode()).hexdigest()
    ocr = mo.ui.anywidget(TesseractOCR(images=ocr_images, angles=list(ROTATIONS), request_key=_key))
    ocr
    return (ocr,)


@app.cell(hide_code=True)
def _(mo):
    mo.md(r"""
    ### Step 4: find the four numbers in each reading

    Each reading is searched line by line for the nutrient names in English
    or French (*Calories*, *Fat / Lipides*, *Carbohydrate / Glucides*,
    *Protein / Protéines*) and the first amount that follows. OCR often reads
    the unit "g" as the digit 8 or 9, so "3.6g" can appear as `3.68` and
    "0.5 g" as `0.5 9`. Gram amounts on these tables have at most one decimal
    place, so a trailing 8 or 9 after the first decimal is read as the unit.
    The six readings of a table then vote: the most frequent value of each
    nutrient is kept, and the agreement column reports how many readings
    found it.
    """)
    return


@app.cell(hide_code=True)
def _(re):
    NUTRIENTS = {
        "calories": r"calor",
        "fat": r"\bfat\b|lip[il]?d",
        "carbohydrate": r"carbo|glucid",
        "protein": r"rotein|prot[eé]in",
    }
    _GRAM = re.compile(r"(\d+(?:[.,]\d+)?)\s*m?g\b")
    _GRAM_MISREAD = re.compile(r"(\d+(?:[.,]\d)?)\s*[89q§]\b")

    def read_amount(text):
        """First gram amount in a string, allowing for a unit misread as 8, 9, or q."""
        for _rx in (_GRAM, _GRAM_MISREAD):
            _m = _rx.search(text)
            if _m:
                _s = _m.group(1).replace(",", ".")
                if re.fullmatch(r"0\d", _s):  # "05g" is 0.5 g with the point lost
                    _s = _s[0] + "." + _s[1]
                return float(_s)
        return None

    def parse_label(text):
        """Calories and fat, carbohydrate, and protein masses from one OCR reading."""
        _found = dict.fromkeys(NUTRIENTS)
        for _line in text.splitlines():
            _line = re.sub(r"\b[Oo](?=\s*m?g\b)", "0", _line)  # "Og" is 0 g
            for _key, _rx in NUTRIENTS.items():
                _m = re.search(_rx, _line.lower())
                if _found[_key] is not None or not _m:
                    continue
                _rest = re.sub(r"^[^\d<]*", "", _line[_m.end():]).lstrip("<")
                if _key == "calories":
                    _n = re.match(r"\d+", _rest)
                    _found[_key] = float(_n.group()) if _n else None
                else:
                    _found[_key] = read_amount(_rest)
        return _found

    return NUTRIENTS, parse_label


@app.cell(hide_code=True)
def _(NUTRIENTS, ROTATIONS, collections, labels, mo, ocr, parse_label):
    _texts = ocr.value.get("texts", [])
    _per_label = len(ROTATIONS) * 2
    mo.stop(ocr.value.get("error"), mo.callout(mo.md(f"OCR failed: {ocr.value.get('error')}"), kind="danger"))
    mo.stop(ocr.value.get("result_key") != ocr.value.get("request_key") or len(_texts) != _per_label * len(labels),
            mo.md("*Waiting for OCR to finish…*"))

    ocr_rows, agreement = [], []
    for _i, (_name, _) in enumerate(labels):
        _readings = [parse_label(t) for t in _texts[_i * _per_label:(_i + 1) * _per_label]]
        _row, _agree = [_name], []
        for _key in NUTRIENTS:
            _votes = collections.Counter(r[_key] for r in _readings if r[_key] is not None)
            if _votes:
                _value, _count = _votes.most_common(1)[0]
                _row.append(f"{_value:g}")
                _agree.append(f"{_count}/{len(_readings)}")
            else:
                _row.append("?")
                _agree.append("–")
        ocr_rows.append(_row)
        agreement.append([_name] + _agree)

    _header = "| food | calories (kcal) | fat (g) | carbohydrate (g) | protein (g) |\n|---|---|---|---|---|\n"
    mo.md("**Readings that agree with the kept value**\n\n" + _header
          + "\n".join("| " + " | ".join(r) + " |" for r in agreement))
    return (ocr_rows,)


