@app.cell(hide_code=True)
def _(label_table, mo, np):
    foods, _rows, _problems = [], [], []
    for _line in label_table.value.strip().splitlines()[1:]:
        _cells = [c.strip() for c in _line.split(",")]
        if len(_cells) != 5:
            _problems.append(f"`{_line}` needs a name and four numbers")
            continue
        try:
            _rows.append([float(c) for c in _cells[1:]])
            foods.append(_cells[0])
        except ValueError:
            _problems.append(f"**{_cells[0]}** has a value that is not a number")
    table = np.array(_rows).reshape(-1, 4)
    mo.stop(len(foods) < 3, mo.callout(mo.md(
        "At least three complete labels are needed. " + "; ".join(_problems)), kind="warn"))
    choice = mo.ui.multiselect(foods, value=foods[:3], label="Three foods for the 3 × 3 system")
    mo.vstack([mo.md("### Step 5: solve for the energy per gram"),
               mo.callout(mo.md("Not used: " + "; ".join(_problems)), kind="warn") if _problems else mo.md(""),
               choice])
    return choice, foods, table


@app.cell(hide_code=True)
def _(choice, foods, mo, np, table):
    mo.stop(len(choice.value) != 3, mo.md("Choose exactly three foods."))
    _idx = [foods.index(f) for f in choice.value]
    A = table[_idx, 1:]
    E = table[_idx, 0]

    def _bmatrix(M):
        M = np.atleast_2d(M)
        return r"\begin{bmatrix}" + r"\\".join(" & ".join(f"{v:g}" for v in row) for row in M) + r"\end{bmatrix}"

    _cond = np.linalg.cond(A)
    mo.stop(not np.isfinite(_cond) or _cond > 1e12, mo.callout(mo.md(
        f"$$\\mathbf{{A}}={_bmatrix(A)}$$ is singular to working precision, "
        "so these three labels cannot determine three factors. Choose a different set."), kind="danger"))
    x = np.linalg.solve(A, E)
    mo.md(
        f"$$\\underbrace{{{_bmatrix(A)}}}_{{\\mathbf{{A}}\\ \\text{{(g)}}}}"
        f"\\begin{{bmatrix}}a\\\\b\\\\c\\end{{bmatrix}}="
        f"\\underbrace{{{_bmatrix(E[:, None])}}}_{{\\mathbf{{E}}\\ \\text{{(kcal)}}}}"
        f"\\quad\\Longrightarrow\\quad"
        f"\\begin{{bmatrix}}a\\\\b\\\\c\\end{{bmatrix}}={_bmatrix(np.round(x, 2)[:, None])}"
        f"\\ \\text{{kcal/g}}$$\n\n"
        f"Rows, top to bottom: {', '.join(choice.value)}. Columns: fat, carbohydrate, protein. "
        f"Condition number $\\kappa(\\mathbf{{A}})$ = {_cond:.3g}. "
        "The standard Atwater factors are 9, 4, and 4 kcal/g."
    )
    return A, E, x


